 return not G.subgraph(B).number_of_edges() and all(len(C)<=len(F) and nx.algorithms.isomorphism.GraphMatcher(F,G.subgraph(C)).subgraph_is_monomorphic()for C in nx.connected_components(G.subgraph(A)))


